read<-function(name) {
  file<-file.path(out,name);header<-strsplit(readLines(file,n=1),",",fixed=TRUE)[[1]]
  types<-cols(.default=col_guess())
  for(key in intersect(header,c("state_fips","county_fips")))types$cols[[key]]<-col_character()
  read_csv(file,show_col_types=FALSE,col_types=types)
}
