f<-function(x,d=3)ifelse(is.finite(x),formatC(x,format="f",digits=d),"unavailable")
ci<-function(d,scale=1,digits=3)paste0(f(d$estimate*scale,digits)," [",f(d$low*scale,digits),", ",f(d$high*scale,digits),"]")
table<-function(d) {
  if(!nrow(d))return("No rows available.\n")
  d<-as.data.frame(d)
  for(k in names(d)) {
    if(is.numeric(d[[k]]))d[[k]]<-ifelse(is.na(d[[k]]),"—",format(d[[k]],digits=5,trim=TRUE,scientific=FALSE))
    d[[k]]<-gsub("|","\\|",replace_na(as.character(d[[k]]),"—"),fixed=TRUE)
  }
  paste(c(paste0("| ",paste(names(d),collapse=" | ")," |"),paste0("| ",paste(rep("---",ncol(d)),collapse=" | ")," |"),
    apply(d,1,function(r)paste0("| ",paste(r,collapse=" | ")," |"))),collapse="\n")
}
