  put("## ",item[[1]]);put("[Full CSV with formula and inference fields](",file.path(out,item[[3]]),")")
  d<-item[[2]]
  put(table(d %>% select(specification,tau,tier,weights,term,status,n,states,estimate,se_jackknife,low,high,p,any_of(c("p_holm","low_simultaneous","high_simultaneous","percent_low","percent_high")))))
}
put("## Original worksite-business benchmarks");put(table(benchmark))
put("## All state-deletion ranges")
for(name in c("wage_state_deletions.csv","admin_state_deletions.csv","earnings_pre_state_deletions.csv")) {
  z<-read(name)
  summary<-z %>% group_by(specification,tau,tier,weights,term) %>% summarise(deletions=n(),unidentified=sum(!is.finite(estimate)),minimum=if(any(is.finite(estimate)))min(estimate,na.rm=TRUE) else NA_real_,maximum=if(any(is.finite(estimate)))max(estimate,na.rm=TRUE) else NA_real_,.groups="drop")
  put("[Every deletion and omitted state: ",name,"](",file.path(out,name),")");put(table(summary))
}
put("## Coverage, exclusions and measurement audits")
for(name in c("wage_composition_coverage.csv","wage_floor_audit.csv","wage_exclusions.csv","admin_exclusions.csv","admin_master_sub_audit.csv","admin_year_means.csv","earnings_pre_coverage.csv","earnings_pre_queue.csv")) {
  put("### ",name);put(table(read(name)))
}
put("## Input hashes and source vintages")
put("These hashes retain the run's evidence record if temporary scratch is later removed. Cache modification time is local provenance, not a verified agency publication date. The official-source URLs are recorded with each QCEW archive. No post-policy archive was opened.")
input_rows<-list()
for(entry in jsonlite::read_json(file.path(out,"inputs.json"))$inputs) {
  stamp<-as.character(as.POSIXct(entry$local_mtime,origin="1970-01-01",tz="UTC"))
  input_rows[[length(input_rows)+1]]<-tibble(Input=entry$path,Bytes=entry$bytes,SHA256=entry$sha256,Cache_mtime_UTC=stamp)
}
put(table(bind_rows(input_rows)))
vintage_rows<-list()
for(entry in jsonlite::read_json(file.path(out,"earnings_pre_inputs.json"))) {
  stamp<-as.character(as.POSIXct(entry$local_mtime,origin="1970-01-01",tz="UTC"))
  vintage_rows[[length(vintage_rows)+1]]<-tibble(Input=basename(entry$file),SHA256=entry$sha256,Source=entry$source_url,Cache_mtime_UTC=stamp)
}
put(table(bind_rows(vintage_rows)))
put("### Frozen declarations and earnings implementation")
put("```text\n",paste(readLines(file.path(CD,"registry.sha256")),collapse="\n"),"\n",paste(readLines(file.path(CD,"earnings_amendment.sha256")),collapse="\n"),"\n```")
writeLines(lines,path_root("markdowns/chapter_directions_specifications.md"))
files<-list.files(CD,recursive=TRUE,full.names=TRUE,pattern="\\.(R|py|json|sha256|sh|md)$")
files<-files[!grepl("__pycache__|__marimo__",files)]
manifest<-list(recorded_at=as.character(Sys.time()),registry_sha256=digest::digest(file=file.path(CD,"registry.json"),algo="sha256"),
  source_hashes=setNames(lapply(files,function(x)digest::digest(file=x,algo="sha256")),files),
  inputs=jsonlite::read_json(file.path(out,"inputs.json")),qcew_vintages=jsonlite::read_json(file.path(out,"earnings_pre_inputs.json")),
  results=list(wage=nrow(w),administration=nrow(a),earnings_pre=nrow(e)),post_policy_earnings_accessed=has_interim,historical_pre_interim_assessment=has_interim,
  report_sha256=digest::digest(file=report,algo="sha256"),appendix_sha256=digest::digest(file=path_root("markdowns/chapter_directions_specifications.md"),algo="sha256"))
jsonlite::write_json(manifest,file.path(out,"report_provenance.json"),auto_unbox=TRUE,pretty=TRUE)
cat("Generated",report,"and complete specification appendix\n")
